package com.ahmedaraby.archive;
import android.content.*;import android.database.Cursor;import android.database.sqlite.*;import java.util.*;
public class ArchiveDb extends SQLiteOpenHelper{
 public static class Item{long id;String title,groupName,notes,tags,fileName,mime,createdAt,backupKey,sha256;boolean favorite,deleted;}
 public static class Group{String name,parent;Group(String n,String p){name=n;parent=p;}}
 ArchiveDb(Context c){super(c,"archive.db",null,5);}
 public void onCreate(SQLiteDatabase d){d.execSQL("CREATE TABLE groups(name TEXT PRIMARY KEY,parent_name TEXT)");d.execSQL("CREATE TABLE items(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,group_name TEXT NOT NULL,notes TEXT,tags TEXT,file_name TEXT NOT NULL,mime TEXT,created_at TEXT NOT NULL,backup_key TEXT UNIQUE,favorite INTEGER NOT NULL DEFAULT 0,deleted INTEGER NOT NULL DEFAULT 0,sha256 TEXT)");for(String n:new String[]{"العمل","القرارات الوزارية","الشهادات","ملفات شخصية"}){ContentValues v=new ContentValues();v.put("name",n);d.insert("groups",null,v);}indexes(d);}
 void indexes(SQLiteDatabase d){d.execSQL("CREATE INDEX IF NOT EXISTS idx_items_group ON items(group_name)");d.execSQL("CREATE INDEX IF NOT EXISTS idx_items_created ON items(created_at)");d.execSQL("CREATE INDEX IF NOT EXISTS idx_items_flags ON items(deleted,favorite)");d.execSQL("CREATE INDEX IF NOT EXISTS idx_items_sha ON items(sha256)");}
 public void onUpgrade(SQLiteDatabase d,int o,int n){if(o<2)d.execSQL("ALTER TABLE groups ADD COLUMN parent_name TEXT");if(o<3){d.execSQL("ALTER TABLE items ADD COLUMN backup_key TEXT");Cursor c=d.rawQuery("SELECT id FROM items WHERE backup_key IS NULL",null);try{while(c.moveToNext()){ContentValues v=new ContentValues();v.put("backup_key",UUID.randomUUID().toString());d.update("items",v,"id=?",new String[]{c.getString(0)});}}finally{c.close();}d.execSQL("CREATE UNIQUE INDEX IF NOT EXISTS items_backup_key ON items(backup_key)");}if(o<4){d.execSQL("ALTER TABLE items ADD COLUMN favorite INTEGER NOT NULL DEFAULT 0");d.execSQL("ALTER TABLE items ADD COLUMN deleted INTEGER NOT NULL DEFAULT 0");}if(o<5)d.execSQL("ALTER TABLE items ADD COLUMN sha256 TEXT");indexes(d);}
 long add(String t,String g,String n,String tags,String f,String m){return add(t,g,n,tags,f,m,null);}
 long add(String t,String g,String n,String tags,String f,String m,String sha){ContentValues v=new ContentValues();v.put("title",t);v.put("group_name",g);v.put("notes",n);v.put("tags",tags);v.put("file_name",f);v.put("mime",m);v.put("created_at",new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm",Locale.US).format(new Date()));v.put("backup_key",UUID.randomUUID().toString());v.put("sha256",sha);return getWritableDatabase().insert("items",null,v);}
 boolean addGroup(String n,String p){ContentValues v=new ContentValues();v.put("name",n);if(p!=null&&!p.isEmpty())v.put("parent_name",p);return getWritableDatabase().insertWithOnConflict("groups",null,v,SQLiteDatabase.CONFLICT_IGNORE)!=-1;}void addGroup(String n){addGroup(n,null);}
 boolean renameGroup(String o,String n){SQLiteDatabase d=getWritableDatabase();d.beginTransaction();try{Cursor c=d.rawQuery("SELECT 1 FROM groups WHERE name=?",new String[]{n});boolean e=c.moveToFirst();c.close();if(e)return false;ContentValues v=new ContentValues();v.put("name",n);d.update("groups",v,"name=?",new String[]{o});v.clear();v.put("parent_name",n);d.update("groups",v,"parent_name=?",new String[]{o});v.clear();v.put("group_name",n);d.update("items",v,"group_name=?",new String[]{o});d.setTransactionSuccessful();return true;}finally{d.endTransaction();}}
 List<String> groups(){List<String> a=new ArrayList<>();Cursor c=getReadableDatabase().rawQuery("SELECT name FROM groups ORDER BY name",null);while(c.moveToNext())a.add(c.getString(0));c.close();return a;}
 List<Group> groupTree(){List<Group>a=new ArrayList<>();Cursor c=getReadableDatabase().rawQuery("SELECT name,parent_name FROM groups ORDER BY parent_name IS NOT NULL,parent_name,name",null);while(c.moveToNext())a.add(new Group(c.getString(0),c.isNull(1)?null:c.getString(1)));c.close();return a;}
 List<String> descendants(String r){List<String>a=new ArrayList<>();a.add(r);boolean x=true;while(x){x=false;for(Group g:groupTree())if(g.parent!=null&&a.contains(g.parent)&&!a.contains(g.name)){a.add(g.name);x=true;}}return a;}
 List<Item> search(String q,String group){return search(q,group,false,false);}List<Item> search(String q,String group,boolean trash,boolean favorites){List<Item>a=new ArrayList<>();String like="%"+(q==null?"":q)+"%";String sql="SELECT id,title,group_name,notes,tags,file_name,mime,created_at,backup_key,favorite,deleted,sha256 FROM items WHERE deleted=? AND (title LIKE ? OR notes LIKE ? OR tags LIKE ? OR file_name LIKE ?)";List<String>args=new ArrayList<>(Arrays.asList(trash?"1":"0",like,like,like,like));if(favorites)sql+=" AND favorite=1";if(group!=null&&!group.isEmpty()){List<String>ns=descendants(group);sql+=" AND group_name IN (";for(int i=0;i<ns.size();i++){if(i>0)sql+=",";sql+="?";args.add(ns.get(i));}sql+=")";}sql+=" ORDER BY favorite DESC,id DESC";Cursor c=getReadableDatabase().rawQuery(sql,args.toArray(new String[0]));while(c.moveToNext()){Item i=new Item();i.id=c.getLong(0);i.title=c.getString(1);i.groupName=c.getString(2);i.notes=c.getString(3);i.tags=c.getString(4);i.fileName=c.getString(5);i.mime=c.getString(6);i.createdAt=c.getString(7);i.backupKey=c.getString(8);i.favorite=c.getInt(9)==1;i.deleted=c.getInt(10)==1;i.sha256=c.getString(11);a.add(i);}c.close();return a;}
 Item find(long id){Cursor c=getReadableDatabase().rawQuery("SELECT id,title,group_name,notes,tags,file_name,mime,created_at,backup_key,favorite,deleted,sha256 FROM items WHERE id=?",new String[]{String.valueOf(id)});try{if(!c.moveToFirst())return null;Item i=new Item();i.id=c.getLong(0);i.title=c.getString(1);i.groupName=c.getString(2);i.notes=c.getString(3);i.tags=c.getString(4);i.fileName=c.getString(5);i.mime=c.getString(6);i.createdAt=c.getString(7);i.backupKey=c.getString(8);i.favorite=c.getInt(9)==1;i.deleted=c.getInt(10)==1;i.sha256=c.getString(11);return i;}finally{c.close();}}
 boolean existsHash(String h){if(h==null)return false;Cursor c=getReadableDatabase().rawQuery("SELECT 1 FROM items WHERE sha256=? AND deleted=0 LIMIT 1",new String[]{h});try{return c.moveToFirst();}finally{c.close();}}
 void edit(long id,String t,String g,String n,String tags){ContentValues v=new ContentValues();v.put("title",t);v.put("group_name",g);v.put("notes",n);v.put("tags",tags);getWritableDatabase().update("items",v,"id=?",new String[]{String.valueOf(id)});}void move(long id,String g){ContentValues v=new ContentValues();v.put("group_name",g);getWritableDatabase().update("items",v,"id=?",new String[]{String.valueOf(id)});}void favorite(long id,boolean x){ContentValues v=new ContentValues();v.put("favorite",x?1:0);getWritableDatabase().update("items",v,"id=?",new String[]{String.valueOf(id)});}void trash(long id,boolean x){ContentValues v=new ContentValues();v.put("deleted",x?1:0);getWritableDatabase().update("items",v,"id=?",new String[]{String.valueOf(id)});}void delete(long id){getWritableDatabase().delete("items","id=?",new String[]{String.valueOf(id)});}
 int restore(List<Group>gs,List<Item>is){SQLiteDatabase d=getWritableDatabase();d.beginTransaction();int n=0;try{for(Group g:gs){ContentValues v=new ContentValues();v.put("name",g.name);v.put("parent_name",g.parent);d.insertWithOnConflict("groups",null,v,SQLiteDatabase.CONFLICT_IGNORE);}for(Item i:is){ContentValues v=new ContentValues();v.put("title",i.title);v.put("group_name",i.groupName);v.put("notes",i.notes);v.put("tags",i.tags);v.put("file_name",i.fileName);v.put("mime",i.mime);v.put("created_at",i.createdAt);v.put("backup_key",i.backupKey);v.put("sha256",i.sha256);if(d.insertWithOnConflict("items",null,v,SQLiteDatabase.CONFLICT_IGNORE)!=-1)n++;}d.setTransactionSuccessful();return n;}finally{d.endTransaction();}}
}
